contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount to forward to c.go; this function is payable so the caller can fund this contract
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to forward");

        // observe owner and balance before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balCBefore = address(c).balance;

        bool reverted;
        // perform the state-changing call as a top-level statement
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint balCAfter = address(c).balance;

        // General invariant: for all inputs, either the call reverted, or owner is unchanged and c.balance is zero
        assert(reverted || (ownerAfter == ownerBefore && balCAfter == 0));
    }

    // allow receiving ether from c or other contracts
    receive() external payable {}
}

